import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi, beforeAll, afterAll } from "vitest";
import SettingsView from "./SettingsView";
import RestaurantContext from "../../context/RestaurantContext";

const mockT = vi.fn((key: string) => key);

vi.mock("react-i18next", () => ({
  useTranslation: () => ({ t: mockT }),
}));

vi.mock("@fortawesome/react-fontawesome", () => ({
  FontAwesomeIcon: ({ icon, ...props }: any) => (
    <svg data-testid="fa-icon" data-icon={icon?.iconName} {...props} />
  ),
}));

vi.mock("qrcode.react", () => ({
  QRCodeSVG: ({ value }: { value: string }) => (
    <svg role="img" data-value={value} />
  ),
}));

vi.mock("../../lib/api", () => ({
  updateRestaurant: vi.fn(),
  triggerTranslation: vi.fn(),
  generateStripeConnectLink: vi.fn(),
  getStripeStatus: vi.fn(),
  disconnectStripe: vi.fn(),
  listStaff: vi.fn().mockResolvedValue([]),
  createStaff: vi.fn(),
  removeStaff: vi.fn(),
  createDeviceEnrollment: vi.fn(),
}));

vi.mock("../../components/ui/BrandingEditor", () => ({
  BrandingEditor: () => <div data-testid="branding-editor" />,
}));

vi.mock("../../components/ui/button", () => ({
  Button: ({ children, ...props }: any) => (
    <button {...props}>{children}</button>
  ),
}));

const mockRestaurant = {
  id: "rest-1",
  name: "Test Restaurant",
  targetLanguages: ["en"],
  timezone: "UTC",
  isLoyaltyEnabled: true,
  loyaltySignupBonus: 50,
  loyaltyExchangeRate: 10,
  loyaltyRedeemRate: 150,
  loyaltyPointExpiryDays: 90,
  loyaltyExpiryReminderDays: 15,
  paymentsEnabled: false,
};

const wrapper = ({ children }: { children: React.ReactNode }) => (
  <RestaurantContext.Provider
    value={{ activeRestaurant: mockRestaurant, fetchRestaurants: vi.fn() } as any}
  >
    {children}
  </RestaurantContext.Provider>
);

beforeAll(() => {
  const store: Record<string, string> = {};
  vi.stubGlobal("localStorage", {
    getItem: (k: string) => store[k] ?? null,
    setItem: (k: string, v: string) => { store[k] = v; },
    removeItem: (k: string) => { delete store[k]; },
    clear: () => { for (const k of Object.keys(store)) delete store[k]; },
  });
});

afterAll(() => {
  vi.unstubAllGlobals();
});

function goToStaffTab() {
  render(<SettingsView />, { wrapper });
  fireEvent.click(screen.getByText("settings.tabs.staff"));
}

describe("SettingsView - Staff tab", () => {
  it("renders Shared Device Mode section after move from General to Staff tab", () => {
    goToStaffTab();
    expect(screen.getByText("Shared Device Mode")).toBeTruthy();
  });

  it("shows Enable button when Shared Device Mode is off", () => {
    goToStaffTab();
    expect(screen.getByText("Enable Shared Device Mode")).toBeTruthy();
  });

  it("shows warning text when Shared Device Mode is off", () => {
    goToStaffTab();
    expect(
      screen.getByText(/Shared Device Mode is currently off/),
    ).toBeTruthy();
  });

  it("toggles Shared Device Mode on and off", () => {
    goToStaffTab();
    const btn = screen.getByText("Enable Shared Device Mode");
    fireEvent.click(btn);
    expect(screen.getByText("Disable Shared Device Mode")).toBeTruthy();
    fireEvent.click(screen.getByText("Disable Shared Device Mode"));
    expect(screen.getByText("Enable Shared Device Mode")).toBeTruthy();
  });
});

